INSERT INTO t_p99892216_child_center_blog.reviews (name, child, text, stars, approved, created_at) VALUES
('Анастасия Цыганкова', NULL, 'Детский сад просто находка для родителей! Хочется отметить профессионализм и доброжелательность воспитателей, чистоту и уют в группах, интересную программу для деток, и поблагодарить за ежедневные видео и фото. Малыш пришел в сад в 1,4. За 2 недели полностью адаптировался и ходит на целый день. В сад бежит с удовольствием! Воспитатели настоящие волшебники. Однозначно рекомендую!', 5, true, '2026-03-18 10:00:00'),
('Полина Савченко', NULL, 'Была в летнем лагере. Было круто) мне очень понравилось, мы готовили, гуляли, веселились!) были крутые вожатые, играли с нами, мы ездили на море, было много крутых мастер классов!) вобщем советую, мне очень понравилось, жду следующего лета', 5, true, '2026-04-23 10:00:00'),
('WinMaria', NULL, 'Место интересного и разнообразного досуга для детей, ходили и в сад и в летний лагерь — всегда разнообразные программы, никогда не повторяются, увлекательные мероприятия, активный досуг для каждого ребенка, учитывая его интересы и хобби! Вожатые внимательные и на одной волне с детьми! Ответственные педагоги и весь персонал, детям нравится, будем ходить дальше!', 5, true, '2026-04-23 11:00:00'),
('Ирина', NULL, 'Отличный садик! Очень классная продлёнка у них! Стоимость небольшая, а входит очень много. Моя дочь очень довольна, не хочет домой уходить 😁', 5, true, '2026-02-21 10:00:00'),
('Карен Даллакян', NULL, 'Прекрасное место для организации досуга и образования детей. Наша семья полностью довольна работой сада. Здесь дети занимаются не только обычными заданиями, но и учатся играть на музыкальных инструментах, петь, танцевать и даже создавать свои маленькие проекты. С уверенностью можем рекомендовать его для всех родителей, которые ищут заботливое и качественное образовательное учреждение для своих детей.', 5, true, '2026-03-21 10:00:00'),
('Н.', NULL, 'Проходили мы туда 3 месяца, я ни разу не пожалела, очень хороший садик', 5, true, '2026-09-02 10:00:00');
